package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"os/signal"
	"strings"
	"syscall"

	"github.com/segmentio/kafka-go"
)

var logger *log.Logger

func init() {
	logger = log.New(os.Stdout, "[stream-processor] ", log.LstdFlags|log.Lshortfile)
}

// ProcessMessage handles incoming Kafka messages from the user-events topic.
// Messages contain JSON payloads with user activity data.
func ProcessMessage(msg kafka.Message) error {
	key := string(msg.Key)
	value := string(msg.Value)

	// Extract correlation ID from headers for distributed tracing
	var correlationID string
	var sourceIP string
	for _, h := range msg.Headers {
		if h.Key == "X-Correlation-ID" {
			correlationID = string(h.Value)
		}
		if h.Key == "X-Forwarded-For" {
			sourceIP = string(h.Value)
		}
	}

	if correlationID == "" {
		correlationID = "unknown"
	}

	// Log the incoming message for audit trail
	logger.Printf("Processing message: key=%s partition=%d offset=%d correlation_id=%s source=%s",
		key, msg.Partition, msg.Offset, correlationID, sourceIP)

	// Validate message isn't empty
	if strings.TrimSpace(value) == "" {
		logger.Printf("WARN: Empty message body received from source=%s correlation_id=%s", sourceIP, correlationID)
		return fmt.Errorf("empty message body")
	}

	// Process based on message key prefix
	switch {
	case strings.HasPrefix(key, "user.login"):
		logger.Printf("INFO: User login event processed: payload_size=%d source=%s correlation_id=%s",
			len(value), sourceIP, correlationID)
	case strings.HasPrefix(key, "user.purchase"):
		logger.Printf("INFO: Purchase event processed: payload_size=%d source=%s correlation_id=%s",
			len(value), sourceIP, correlationID)
	case strings.HasPrefix(key, "user.logout"):
		logger.Printf("INFO: Logout event processed: payload_size=%d source=%s correlation_id=%s",
			len(value), sourceIP, correlationID)
	default:
		logger.Printf("WARN: Unknown event type key=%s source=%s correlation_id=%s",
			key, sourceIP, correlationID)
	}

	return nil
}

func main() {
	broker := os.Getenv("KAFKA_BROKER")
	if broker == "" {
		broker = "localhost:9092"
	}

	topic := os.Getenv("KAFKA_TOPIC")
	if topic == "" {
		topic = "user-events"
	}

	groupID := os.Getenv("KAFKA_GROUP_ID")
	if groupID == "" {
		groupID = "stream-processor-group"
	}

	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  []string{broker},
		Topic:    topic,
		GroupID:  groupID,
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	defer reader.Close()

	logger.Printf("Starting consumer: broker=%s topic=%s group=%s", broker, topic, groupID)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-sigChan
		logger.Println("Shutdown signal received")
		cancel()
	}()

	for {
		msg, err := reader.ReadMessage(ctx)
		if err != nil {
			if ctx.Err() != nil {
				break
			}
			logger.Printf("ERROR: Failed to read message: %v", err)
			continue
		}

		if err := ProcessMessage(msg); err != nil {
			logger.Printf("ERROR: Failed to process message at offset %d: %v", msg.Offset, err)
		}
	}

	logger.Println("Consumer shutdown complete")
}
